```js
// webhook.js
const express = require('express');
const Stripe = require('stripe');

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY);
const endpointSecret = process.env.STRIPE_WEBHOOK_SECRET;

const app = express();

// Raw body only for this route. Must come before any app.use(express.json()).
app.post(
  '/webhooks/stripe',
  express.raw({ type: 'application/json' }),
  (req, res) => {
    const signature = req.headers['stripe-signature'];

    let event;
    try {
      event = stripe.webhooks.constructEvent(req.body, signature, endpointSecret);
    } catch (err) {
      console.error(`Stripe signature verification failed: ${err.message}`);
      return res.status(400).send(`Webhook Error: ${err.message}`);
    }

    if (event.type === 'payment_intent.succeeded') {
      const paymentIntent = event.data.object;
      console.log('payment_intent.succeeded', {
        id: paymentIntent.id,
        amount: paymentIntent.amount,
        currency: paymentIntent.currency,
        customer: paymentIntent.customer,
        created: new Date(paymentIntent.created * 1000).toISOString(),
        eventId: event.id,
      });
    }

    // Acknowledge every verified event, including types we don't handle.
    res.json({ received: true });
  }
);

app.use(express.json());
// ...other routes

app.listen(3000);
```

Notes:

- **Verification:** `constructEvent` checks the `Stripe-Signature` header against the raw body and rejects requests older than the default 5-minute tolerance, which guards against replay.
- **Secret:** `STRIPE_WEBHOOK_SECRET` is the signing secret for this endpoint (`whsec_...`), shown in the Dashboard or by `stripe listen`. It is not your API secret key.
- **Logging:** this logs only a few fields. Avoid logging full payment objects, since they can contain customer data.
- **Retries:** Stripe retries any non-2xx response, so return 500 only for failures you want retried. If your logging or downstream work can fail, do it inside a try block and return 500 on error.
- **Local testing:** `stripe listen --forward-to localhost:3000/webhooks/stripe` prints a signing secret to use for `STRIPE_WEBHOOK_SECRET`.

