#!/usr/bin/env bash
# Stop gate: keep Claude working until `npm test` passes.
# Exit 2 blocks the stop and feeds the output back to Claude.

# Hook input arrives on stdin; drain it so the harness isn't blocked on write.
cat > /dev/null

cd "${CLAUDE_PROJECT_DIR:-.}" || {
  echo "stop-gate: cannot cd to project directory" >&2
  exit 2
}

output=$(npm test 2>&1)
status=$?

if [ "$status" -eq 0 ]; then
  exit 0
fi

{
  echo "Stop blocked: \`npm test\` is failing (exit $status). Fix the failures and try again."
  echo
  printf '%s\n' "$output" | tail -n 200
} >&2
exit 2
EOF
